'use strict';
const icon=(name,size=18)=>{const paths={board:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M9 3v18M15 3v18M5.5 7h1M11.5 7h1M17.5 7h1M5.5 11h1M11.5 11h1"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6M21 20v-2a6 6 0 0 0-3-5"/>',agent:'<rect x="4" y="6" width="16" height="14" rx="4"/><path d="M12 3v3M8 11v2M16 11v2M8 16h8M1 11v4M23 11v4"/>',mission:'<rect x="4" y="4" width="16" height="18" rx="2"/><path d="M9 4V2h6v2M8 11l2 2 5-5M8 17h8"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',chevron:'<path d="m8 10 4 4 4-4"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',shield:'<path d="m12 3 8 3v5c0 5-3 8-8 10-5-2-8-5-8-10V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',reset:'<path d="M3 10a9 9 0 1 1 1 8M3 4v6h6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',check:'<path d="m5 12 4 4L19 6"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12h18M10 12v3h4v-3"/>',play:'<path d="m8 4 12 8-12 8Z"/>',dots:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',file:'<path d="M14 2H5v20h14V7l-5-5Z M14 2v6h5M8 12h8M8 16h6"/>',grip:'<path d="M9 5h.01M15 5h.01M9 12h.01M15 12h.01M9 19h.01M15 19h.01"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.file}</svg>`};
const brand=`<svg width="33" height="33" viewBox="0 0 216 216" fill="#d79376" aria-hidden="true"><g transform="translate(.5 2)"><path d="M26 108V43c0-10 8-18 18-18h54c56 0 91 33 91 81s-35 81-91 81H45l34-34h19c35 0 56-17 56-47s-21-47-56-47H60v49Z"/><rect x="26" y="125" width="34" height="34" rx="4"/></g></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'¥'+Number(n).toLocaleString('zh-CN',{maximumFractionDigits:0});
const stages=['新客户','已联系','方案沟通','已成交'];
const initialContacts=[['c1','林晓梅','lin.xiaomei@example.test','官网咨询','待跟进','云禾设计'],['c2','陈伟','chen.wei@example.test','线下活动','待跟进','拾光零售'],['c3','王芳','wang.fang@example.test','朋友推荐','重点客户','青禾品牌'],['c4','赵强','zhao.qiang@example.test','官网咨询','重点客户','远山科技'],['c5','周敏','zhou.min@example.test','朋友推荐','已成交','星辰咨询']].map(([id,name,email,source,tag,company])=>({id,name,email,source,tag,company,phone:'演示号码 · 未连接'}));
const initialLeads=[{id:'l1',title:'林晓梅 — 企业官网改版',cid:'c1',stage:0,value:12800,risk:true,activity:'2 小时前',next:'今天 14:00 · 确认需求',notes:'希望重新梳理官网内容与询盘路径。需确认上线时间与页面范围。'}, {id:'l2',title:'陈伟 — 门店会员系统',cid:'c2',stage:1,value:7600,risk:false,activity:'昨天',next:'明天 10:00 · 需求回访',notes:'已有两家门店，希望整合会员积分与到店记录。'}, {id:'l3',title:'王芳 — 私域运营方案',cid:'c3',stage:2,value:24500,risk:false,activity:'3 小时前',next:'今天 16:00 · 方案复核',notes:'第一版方案已沟通，等待内部复核服务范围和交付时间。'}, {id:'l4',title:'赵强 — 年度服务合同',cid:'c4',stage:2,value:52000,risk:true,activity:'8 天前',next:'待确认 · 合同跟进',notes:'已沟通年度服务范围，客户尚未确认报价与交期。不能将模型回复作为业务完成依据。'}, {id:'l5',title:'周敏 — 已签约客户',cid:'c5',stage:3,value:9800,risk:false,activity:'昨天',next:'已完成 · 签约交接',notes:'演示记录：已签约，进入客户交接。'}];
const agents=[{name:'CRM 情报员',desc:'汇总客户、会话、商机、任务与知识中的证据，回答业务问题。',scenarios:[['客户 360 摘要','请总结这个客户近期的沟通、商机和待办，并列出依据。'],['停滞商机原因','找出最近停滞的商机，基于会话和活动说明可能原因。'],['知识依据核对','查询知识库中与这个客户问题相关的内容，并指出哪些问题仍缺少依据。']]},{name:'销售运营 Agent',desc:'发现漏斗跟进缺口，并在授权范围内提出或执行 CRM 内部操作。',scenarios:[['找出待跟进商机','列出超过一周没有跟进的开放商机，并按风险排序。'],['补一条跟进任务','为选中的商机安排明天的跟进任务，并说明任务内容。'],['整理商机阶段','检查商机阶段，提出调整建议与下一步跟进。']]},{name:'客户沟通 Agent',desc:'结合会话和知识起草回复；发送、转人工等动作由 Harness 守门。',scenarios:[['拟一条有依据的回复','阅读最近会话和相关知识，为客户起草回复，不要发送。'],['检查承诺风险','检查拟发送的回复是否包含知识库没有支持的承诺。'],['识别人工接管','查看这段会话是否应交给人工，并解释触发依据。']]},{name:'CRM 主管 Agent',desc:'跨漏斗、任务与执行记录发现运营异常，给出可审核的修复计划。',scenarios:[['漏斗健康检查','检查各阶段商机数量和停滞情况，指出最值得优先处理的问题。'],['跟进队列盘点','汇总逾期任务及其关联商机，提出一份分批处理计划。'],['运行成本复盘','汇总近期 Agent 执行的次数、工具失败和用量异常。']]}];
const fresh=()=>({leads:structuredClone(initialLeads),contacts:structuredClone(initialContacts),missions:[{id:'m1',leadId:'l4',goal:'确认年度合同报价与交期',acceptance:'客户确认报价与交期，商机记录和下一次跟进均已更新',status:'等待客户',paused:false,direction:'先核对服务范围，再与客户确认交付日期。',history:['09:20 · 建立业务任务（演示）','09:21 · Agent 本轮结束，业务结果仍待验收'],eval:false}],runs:[],tasks:[],page:'kanban',q:'',filter:'all',tag:'all',source:'all',agent:0,scope:'l4',mode:'inspect',task:'',chatId:'chat-1',chatCounter:1,agentPanel:null,delegate:false,acceptance:'客户确认报价与交期，商机记录和下一次跟进均已更新',observed:'',detail:null,busy:false,drawer:null,drawerTab:'info'});
let state=fresh(),runTimer=null,toastTimer=null;
const contact=id=>state.contacts.find(c=>c.id===id);const lead=id=>state.leads.find(l=>l.id===id);const selectedLead=()=>lead(state.scope);const navNames={kanban:'销售漏斗',contacts:'联系人',workbench:'Agent 工作台',missions:'业务任务'};
function toast(message){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=message;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3800)}
function navigate(page){if(!Object.hasOwn(navNames,page))return;state.page=page;state.q='';state.filter='all';state.tag='all';state.source='all';state.drawer=null;render();window.scrollTo?.(0,0)}
function render(){const active=document.activeElement;const focusId=active?.id;const position=active?.selectionStart;document.getElementById('app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand">${brand}<div>Pi Native <small>CRM</small></div></div><nav aria-label="主导航"><div class="navlabel">CRM</div>${navButton('kanban','board')}${navButton('contacts','users')}<div class="navlabel">人工智能</div>${navButton('workbench','agent')}${navButton('missions','mission')}</nav><div class="sidebottom"><strong>演示工作区</strong><br>界面交互演示<br>所有数据均为虚构</div></aside><div class="mainwrap"><header class="topbar"><div class="row"><span class="mobilebrand">${brand}</span><span class="workspace">演示工作区</span>${icon('chevron',14)}<span class="top-divider"></span><span class="small muted desktop-only">${navNames[state.page]}</span></div><div class="row"><span class="badge top-meta">${icon('lock',12)} 私有演示</span><button class="btn ghost small" data-action="reset">${icon('reset',15)} 重置演示</button><span class="avatar">演</span><span class="small user-label">演示账号</span></div></header><div class="demobar">${icon('shield',15)}<span>模拟演示 · 虚构数据<span class="desktop-only"> · 更改仅在当前页面有效</span> · 不调用真实模型，不向客户发送消息</span></div><main class="main" id="main">${state.page==='kanban'?boardView():state.page==='contacts'?contactsView():state.page==='workbench'?workbenchView():missionsView()}</main></div></div>${state.drawer?drawerView():''}`;bind();if(focusId){const el=document.getElementById(focusId);if(el){el.focus();if(typeof position==='number'&&typeof el.setSelectionRange==='function')try{el.setSelectionRange(position,position)}catch{}}}}
function navButton(page,i){return `<button class="navitem ${state.page===page?'active':''}" data-page="${page}" ${state.page===page?'aria-current="page"':''}>${icon(i)}${navNames[page]}</button>`}
function boardView(){const list=state.leads.filter(l=>(l.title+' '+contact(l.cid)?.name).toLowerCase().includes(state.q.toLowerCase())&&(state.filter==='all'||state.filter==='risk'&&l.risk||state.filter==='open'&&l.stage!==3||state.filter==='won'&&l.stage===3));return `<div class="pagehead"><div><p class="eyebrow">CRM / 销售漏斗</p><h1>演示销售漏斗</h1><p class="subtitle">从新客户到成交，在同一个看板推进每一笔商机</p></div><button class="btn primary" data-action="new-lead">${icon('plus',16)} 新建商机</button></div><div class="toolbar"><div class="search">${icon('search',16)}<input class="input" id="board-search" aria-label="搜索商机" placeholder="搜索客户或商机…" value="${esc(state.q)}"></div><select id="board-filter" aria-label="商机筛选"><option value="all" ${state.filter==='all'?'selected':''}>全部商机</option><option value="open" ${state.filter==='open'?'selected':''}>进行中</option><option value="risk" ${state.filter==='risk'?'selected':''}>需要跟进</option><option value="won" ${state.filter==='won'?'selected':''}>已成交</option></select><span class="grow"></span><span class="small muted filtercount">${list.length} 个商机 · ${money(list.reduce((s,l)=>s+l.value,0))}</span></div><div class="board" aria-label="商机看板">${stages.map((s,i)=>{let ls=list.filter(l=>l.stage===i);return `<section class="stage" data-stage="${i}" aria-label="${s}"><div class="stage-title"><span class="dot" style="background:${['#a5957c','#506e8a','#b05a3d','#5e8b62'][i]}"></span><h2>${s}</h2><span class="count">${ls.length}</span></div><div class="stage-sum">${money(ls.reduce((sum,l)=>sum+l.value,0))}</div><div class="stage-cards">${ls.map(cardView).join('')}${!ls.length?'<div class="empty">暂无商机</div>':''}<button class="stage-add" data-action="new-lead" data-stage="${i}">${icon('plus',14)} 添加商机</button></div></section>`}).join('')}</div><div class="footnote">${icon('info',14)} 拖动卡片调整阶段，或打开详情选择阶段 · 刷新页面会恢复初始数据</div>`}
function cardView(l){const c=contact(l.cid);return `<article class="lead ${l.risk?'risk':''}" draggable="true" data-lead-drag="${l.id}"><button class="lead-title" data-lead="${l.id}">${esc(l.title)}</button><div class="row between"><span class="amount">${money(l.value)}</span>${l.stage===3?'<span class="badge good">已成交</span>':l.risk?'<span class="badge warn">待跟进</span>':'<span class="badge">进行中</span>'}</div><div class="contactline">${icon('users',13)}${esc(c?.company||c?.name||'新客户')}</div><div class="small ${l.risk?'':'muted'}" style="color:${l.risk?'var(--warning)':''}">${icon('clock',13)} ${esc(l.next)}</div><div class="lead-footer" style="margin-top:12px"><span class="row gap6"><span class="avatar" style="width:20px;height:20px;font-size:.6rem">演</span>演示账号</span><span>${esc(l.activity)}</span></div></article>`}
function contactsView(){const cs=state.contacts.filter(c=>(c.name+c.email+c.company).toLowerCase().includes(state.q.toLowerCase())&&(state.tag==='all'||c.tag===state.tag)&&(state.source==='all'||c.source===state.source));return `<div class="pagehead"><div><p class="eyebrow">CRM / 联系人</p><h1>联系人</h1><p class="subtitle">Customer 360 · 搜索、筛选和管理联系人</p></div><button class="btn primary" data-action="new-contact">${icon('plus',16)} 新建联系人</button></div><div class="toolbar"><div class="search">${icon('search',16)}<input class="input" id="contact-search" aria-label="搜索联系人" placeholder="搜索姓名、邮箱或公司…" value="${esc(state.q)}"></div><select id="contact-tag" aria-label="标签筛选">${['all','待跟进','重点客户','已成交'].map(t=>`<option value="${t}" ${state.tag===t?'selected':''}>${t==='all'?'标签：全部':t}</option>`).join('')}</select><select id="contact-source" aria-label="来源筛选">${['all','官网咨询','线下活动','朋友推荐','手动添加'].map(t=>`<option value="${t}" ${state.source===t?'selected':''}>${t==='all'?'来源：全部':t}</option>`).join('')}</select></div><div class="tablebox"><table><thead><tr><th>姓名</th><th>邮箱</th><th>电话</th><th>标签</th><th>最近活动</th><th>状态</th><th>操作</th></tr></thead><tbody>${cs.map(c=>`<tr><td><button class="textbtn row" data-contact="${c.id}"><span class="avatar">${esc(c.name.slice(-2))}</span>${esc(c.name)}</button></td><td class="muted">${esc(c.email)}</td><td>演示号码 · 未连接</td><td><span class="badge ${c.tag==='重点客户'?'clay':c.tag==='已成交'?'good':''}">${esc(c.tag)}</span></td><td class="muted">今天</td><td><span class="badge good">活跃</span></td><td><button class="btn small" data-contact="${c.id}">查看档案</button></td></tr>`).join('')}</tbody></table>${!cs.length?'<div class="empty">没有符合条件的联系人，请调整搜索或筛选</div>':''}<div class="tablefooter">共 ${cs.length} 位联系人 · 所有联系方式均为虚构示例</div></div>`}
function workbenchView(){
  const a=agents[state.agent],d=state.detail,l=selectedLead();
  const turns=state.runs.filter(r=>r.chatId===state.chatId);
  if(d&&d.chatId===state.chatId&&!turns.some(r=>r.id===d.id))turns.push(d);
  return `<section class="agent-workspace" aria-label="Agent 对话工作区">
    <header class="agent-chat-header"><div class="agent-identity"><span class="agent-symbol">${icon('agent',21)}</span><div><h1>Agent 对话</h1><select id="agent-picker" aria-label="选择 Agent" ${state.busy?'disabled':''}>${agents.map((a,i)=>`<option value="${i}" ${state.agent===i?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div></div><div class="agent-header-actions"><button class="btn ghost" data-action="new-chat" ${state.busy?'disabled':''} aria-label="新对话">${icon('plus',15)}<span>新对话</span></button><button class="btn" data-action="agent-settings" aria-label="上下文与设置" aria-expanded="${state.agentPanel==='settings'}">${icon('briefcase',15)}<span>上下文</span></button><button class="btn" data-action="agent-details" aria-label="任务与记录" aria-expanded="${state.agentPanel==='details'}">${icon('file',15)}<span>任务与记录</span>${d?.proposal==='pending'?'<i class="pending-dot" aria-label="有待确认动作"></i>':''}</button></div></header>
    <div class="agent-contextbar"><span class="context-label">目标商机</span><button data-action="agent-settings" title="切换目标商机">${esc(l?.title||'未选择商机')}${icon('chevron',12)}</button><span class="badge ${state.mode==='act'?'warn':''}">${state.mode==='act'?'分级自治 · 模拟':'只读检查'}</span></div>
    <div id="agent-conversation" class="agent-conversation" role="log" aria-label="Agent 对话记录" aria-live="polite" tabindex="0"><div class="agent-conversation-inner">${turns.length?turns.map(chatTurnView).join(''):`<div class="agent-welcome"><span class="welcome-symbol">${brand}</span><h2>今天想推进哪一项工作？</h2><p>${esc(a.desc)}</p><div class="agent-prompts">${a.scenarios.map((q,i)=>`<button data-scenario="${i}" class="agent-prompt">${esc(q[0])}<span aria-hidden="true">↗</span></button>`).join('')}</div><span class="small subtle">选择一个问题，或直接在下方输入</span></div>`}</div></div>
    <form id="agent-chat-form" class="agent-composer" aria-label="发送 Agent 任务"><div class="agent-composer-box"><label class="sr-only" for="agent-task">Agent 任务目标</label><textarea id="agent-task" name="task" rows="2" maxlength="4000" placeholder="给 ${esc(a.name)} 发消息…" ${state.busy?'disabled':''}>${esc(state.task)}</textarea><div class="agent-composer-tools"><label class="agent-mode-label"><span class="sr-only">执行模式</span><select id="run-mode" ${state.busy?'disabled':''}><option value="inspect" ${state.mode==='inspect'?'selected':''}>只读检查</option><option value="act" ${state.mode==='act'?'selected':''}>分级自治 · 模拟</option></select></label><span class="agent-key-hint">Enter 发送 · Shift + Enter 换行</span>${state.busy?'<button type="button" class="btn" data-action="cancel-run">■ 停止模拟</button>':`<button type="submit" class="btn primary agent-send" id="run-button" ${!state.task.trim()?'disabled':''} aria-label="发送任务（模拟）">${icon('arrow',16)}<span>发送</span></button>`}</div></div><p class="agent-disclaimer">预设模拟回复 · 未接入真实 AI · 不向客户发送消息</p></form>
    ${state.agentPanel?agentSidePanel():''}
  </section>`;
}
function chatTurnView(d){return `<article class="agent-turn" data-turn="${d.id}"><div class="user-message"><span class="sr-only">你：</span>${esc(d.task)}</div><div class="assistant-message"><div class="assistant-label">${icon('agent',16)}<strong>${esc(d.agent)}</strong><span>模拟回复</span></div>${d.final?`<p class="assistant-answer">${esc(d.final)}</p>`:`<p class="agent-working">${d.status==='cancelled'?'本次模拟已停止':esc(d.events.at(-1)?.[0]||'正在准备模拟回复…')}${d.status==='running'?'<span class="typing-dots" aria-hidden="true"> ···</span>':''}</p>`}<details class="agent-trace" data-trace="${d.id}"><summary>${d.events.length} 步执行记录${d.status==='cancelled'?' · 已停止':''}</summary>${d.events.map((e,i)=>`<div class="event"><span class="eventmark">${i+1}</span><div><strong>${esc(e[0])}</strong><p>${esc(e[1])}</p></div></div>`).join('')}</details>${d.write||d.draft?`<button class="agent-result-link" data-run-details="${d.id}">${d.proposal==='pending'?'查看待确认草稿与 CRM 变更':'查看草稿与任务详情'} ${icon('arrow',13)}</button>`:''}</div></article>`}
function agentSidePanel(){const settings=state.agentPanel==='settings',d=state.detail;return `<button class="agent-panel-scrim" data-action="close-agent-panel" aria-label="关闭 Agent 详情"></button><aside class="agent-sidepanel" role="dialog" aria-modal="true" aria-label="${settings?'Agent 上下文与设置':'任务与运行记录'}"><div class="agent-panel-head"><h2>${settings?'上下文与设置':'任务与运行记录'}</h2><button class="btn ghost iconbtn" data-action="close-agent-panel" aria-label="关闭 Agent 详情">${icon('close',17)}</button></div><div class="agent-panel-body">${settings?`<p class="small muted">${esc(agents[state.agent].desc)}</p><label class="field">目标商机<select id="agent-scope" ${state.busy?'disabled':''}>${state.leads.map(x=>`<option value="${x.id}" ${state.scope===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><p class="small muted">执行模式可以在聊天输入框下方切换。</p>${state.mode==='act'&&selectedLead()?`<div class="subpanel"><label class="checkrow"><input id="delegate" type="checkbox" ${state.delegate?'checked':''} ${state.busy?'disabled':''}>建立商机业务任务</label>${state.delegate?`<label class="field" style="margin-top:10px">业务验收条件<textarea id="acceptance" rows="3" ${state.busy?'disabled':''}>${esc(state.acceptance)}</textarea></label><p class="small muted" style="margin-top:8px">本轮结束后，业务结果仍需人工验收。</p>`:''}</div>`:'<div class="banner">只读检查不会创建业务任务或修改 CRM。</div>'}<div class="subpanel"><h3>工具与权限</h3><p class="small muted">读取虚构 CRM 上下文</p><p class="small muted">本地跟进任务可以撤销</p><p class="small muted">客户发送只有草稿与确认模拟</p></div>`:d?resultPanel(d):'<p class="muted small">发送一条任务后，这里显示运行详情与待确认动作。</p>'}<div class="divider"></div><h3>最近对话</h3>${state.runs.length?state.runs.slice().reverse().slice(0,10).map(r=>`<button class="run-history" data-run="${r.id}" ${state.busy?'disabled':''}>${esc(r.task)}<br><span class="subtle">${esc(r.agent)} · ${r.status==='cancelled'?'已停止':'已结束（模拟）'}</span></button>`).join(''):'<p class="small subtle">暂无对话记录</p>'}<div class="agent-panel-links"><button class="btn small" data-page="/app/ai/agents">智能体配置</button><button class="btn small" data-page="/app/missions">业务任务</button><button class="btn small" data-page="/app/ai/runs">执行记录</button></div></div></aside>`}
function newAgentChat(agent=state.agent){if(state.busy)return;state.agent=agent;state.mode='inspect';state.delegate=false;state.chatId='chat-'+(++state.chatCounter);state.detail=null;state.task='';state.agentPanel=null;render();document.getElementById('agent-task')?.focus()}
function setAgentMode(mode){state.mode=mode;if(mode==='inspect')state.delegate=false;render()}
function openAgentPanel(panel){state.agentPanel=panel;render();document.querySelector('.agent-sidepanel [data-action="close-agent-panel"]')?.focus()}
function bindAgentChat(){
  const form=document.getElementById('agent-chat-form');if(form)form.onsubmit=e=>{e.preventDefault();runAgent()};
  const input=document.getElementById('agent-task');if(input){input.oninput=()=>{state.task=input.value;const send=document.getElementById('run-button');if(send)send.disabled=state.busy||!state.task.trim()};input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&!state.busy){e.preventDefault();runAgent()}}}
  const picker=document.getElementById('agent-picker');if(picker)picker.onchange=()=>newAgentChat(Number(picker.value));
  document.querySelectorAll('[data-run-details]').forEach(el=>el.onclick=()=>{if(state.busy)return;state.detail=state.runs.find(r=>r.id===el.dataset.runDetails)||state.detail;openAgentPanel('details')});
  document.querySelectorAll('[data-scenario]').forEach(el=>el.onclick=()=>{if(state.busy)return;state.task=agents[state.agent].scenarios[Number(el.dataset.scenario)][1];if(state.agent===1&&Number(el.dataset.scenario)===1)state.mode='act';render();document.getElementById('agent-task')?.focus()});
}
function resultPanel(d){const m=state.missions.find(m=>m.id===d.missionId);return `<div class="subpanel" style="background:var(--elevated)"><div class="kv"><span class="muted">运行状态</span><span class="badge ${d.status==='running'?'info':d.status==='cancelled'?'':'good'}">${d.status==='running'?'运行中':d.status==='cancelled'?'已取消':'本轮已结束'}</span></div><div class="kv"><span class="muted">模式</span><span>${d.mode==='act'?'分级自治':'只读检查'}</span></div></div>${m?`<div class="subpanel"><h3>商机业务任务</h3><span class="badge warn mission-status">${esc(m.status)}</span><p style="margin-top:9px">${esc(m.goal)}</p><p class="small muted">验收：${esc(m.acceptance)}</p><button class="textbtn" data-mission="${m.id}" style="margin-top:9px">查看任务与验收</button></div>`:''}${d.write?`<div class="subpanel"><h3>${d.undone?'已撤销模拟变更':'CRM 内部变更'}</h3><p class="small">${d.undone?'跟进任务已从本地演示数据移除':'已创建明天的跟进任务（本地）'}</p>${!d.undone?`<button class="btn small" data-action="undo" style="margin-top:10px">撤销变更</button>`:''}</div>`:''}${d.draft?`<div class="subpanel"><div class="row between"><h3>Agent 回复草稿</h3><span class="badge">${d.proposal==='approved'?'模拟已入队':d.proposal==='rejected'?'已拒绝':d.proposal==='expired'?'已失效 · 需重新审核':'未发送'}</span></div><p class="small" style="margin-top:8px">${esc(d.draft)}</p><p class="small subtle" style="margin-top:9px">本演示无发送通道，不会触达客户</p>${d.mode==='act'&&d.proposal==='pending'?`<div class="stack" style="margin-top:12px"><button class="btn small primary" data-action="approve">模拟批准入队</button><button class="btn small" data-action="reject">拒绝</button></div>`:''}</div>`:''}${d.status==='completed'?`<div class="subpanel"><h3>Harness 记录</h3><p class="small muted">${d.events.length} 个演示事件 · ${d.write?1:0} 次本地变更</p><p class="small muted">真实发送：0 · 模型用量：0</p></div>`:''}`}
function missionsView(){return `<div class="pagehead"><div><p class="eyebrow">人工智能 / Mission</p><h1>Agent 业务任务</h1><p class="subtitle">追踪业务结果；一次 Agent 执行结束不代表任务已经完成</p></div><button class="btn primary" data-action="delegate-new">${icon('plus',16)} 委托新任务</button></div><div class="summarystrip"><span><strong>${state.missions.filter(m=>m.status!=='已完成').length}</strong>等待业务结果</span><span><strong>${state.missions.filter(m=>m.status==='已完成').length}</strong>人工已验收</span><span><strong>${state.missions.filter(m=>m.paused).length}</strong>暂停客户发送</span></div><div class="missionlist">${state.missions.map(m=>`<article class="panel missioncard"><div class="row between wrap"><h2>${esc(m.goal)}</h2><span class="badge ${m.status==='已完成'?'good':'warn'}">${esc(m.status)}</span></div><p class="subtitle">${esc(lead(m.leadId)?.title)}</p><div class="meta"><span>验收：${esc(m.acceptance)}</span></div>${m.paused?'<div class="banner">客户发送已暂停；旧审批不能继续发送（模拟策略）</div>':''}<div class="mission-actions"><button class="btn small primary" data-mission="${m.id}">查看任务详情</button><button class="btn small" data-lead="${m.leadId}">查看商机</button></div></article>`).join('')}</div>`}
function drawerView(){const dr=state.drawer;if(dr.kind==='contact'){const c=contact(dr.id);return overlay(`<div class="drawer-head"><div class="row between"><div><p class="eyebrow">联系人 / Customer 360</p><h1>${esc(c.name)}</h1></div>${closeButton()}</div></div><div class="drawer-body"><div class="panel panel-pad stack"><div class="kv"><span class="muted">公司</span><span>${esc(c.company||'—')}</span></div><div class="kv"><span class="muted">邮箱</span><span style="overflow-wrap:anywhere">${esc(c.email||'—')}</span></div><div class="kv"><span class="muted">来源</span><span>${esc(c.source)}</span></div><div class="kv"><span class="muted">标签</span><span class="badge">${esc(c.tag)}</span></div></div><h2 style="margin:24px 0 12px">关联商机</h2>${state.leads.filter(l=>l.cid===c.id).map(l=>`<div style="margin-bottom:10px">${cardView(l)}</div>`).join('')||'<p class="muted small">暂无关联商机</p>'}<p class="notice-inline">以上联系人与联系方式均为虚构数据</p></div>`)}if(dr.kind==='mission'){const m=state.missions.find(x=>x.id===dr.id);return overlay(`<div class="drawer-head"><div class="row between"><div><p class="eyebrow">Mission / 商机业务任务</p><h1>任务详情与验收</h1></div>${closeButton()}</div></div><div class="drawer-body">${missionDetail(m)}</div>`)}const l=lead(dr.id),c=contact(l.cid);return overlay(`<div class="drawer-head"><div class="row between"><span class="badge">商机详情</span>${closeButton()}</div><h1 style="margin-top:13px;font-size:1.4rem">${esc(l.title)}</h1><p class="subtitle">${esc(c?.company||'演示客户')} · ${esc(c?.name||'新客户')}</p></div><div class="drawer-body"><div class="tabs"><button class="tab ${state.drawerTab==='info'?'active':''}" data-tab="info">基本信息</button><button class="tab ${state.drawerTab==='mission'?'active':''}" data-tab="mission">Agent 业务任务 <span class="small">${state.missions.filter(m=>m.leadId===l.id).length}</span></button></div>${state.drawerTab==='info'?`<div class="panel panel-pad stack"><div class="kv"><span class="muted">商机金额</span><strong>${money(l.value)}</strong></div><label class="field">当前阶段<select id="detail-stage">${stages.map((s,i)=>`<option value="${i}" ${l.stage===i?'selected':''}>${s}</option>`).join('')}</select></label><div class="kv"><span class="muted">负责人</span><span>演示账号</span></div><div class="kv"><span class="muted">下一次跟进</span><span>${esc(l.next)}</span></div><div class="kv"><span class="muted">联系人</span><button class="textbtn" data-contact="${l.cid}">${esc(c?.name)}</button></div></div><div class="panel panel-pad" style="margin-top:14px"><h3>商机备注</h3><p class="small muted" style="margin-top:10px">${esc(l.notes)}</p></div><h3 style="margin:24px 0 12px">待办任务</h3>${state.tasks.filter(t=>t.leadId===l.id).map(t=>`<div class="subpanel small">${icon('mission',15)} ${esc(t.title)}<br><span class="subtle">明天 10:00 · 演示账号</span></div>`).join('')||'<p class="small subtle">暂无 Agent 新建的跟进任务</p>'}<button class="btn primary" style="margin-top:24px;width:100%" data-delegate-lead="${l.id}">${icon('agent',16)} 委托 Agent 跟进</button>`:`${state.missions.filter(m=>m.leadId===l.id).map(m=>`<div style="margin-bottom:16px">${missionDetail(m)}</div>`).join('')||'<p class="small muted">这个商机还没有委托任务</p>'}<button class="btn primary" style="margin-top:18px" data-delegate-lead="${l.id}">委托新任务</button>`}</div>`)}
function missionDetail(m){return `<div class="panel panel-pad"><div class="row between wrap"><h2>${esc(m.goal)}</h2><span class="badge ${m.status==='已完成'?'good':'warn'}">${esc(m.status)}</span></div><p class="subtitle">${esc(lead(m.leadId)?.title)}</p><div class="divider"></div><p class="small"><strong>验收条件</strong></p><p class="small muted" style="margin-top:6px">${esc(m.acceptance)}</p><p class="small" style="margin-top:15px"><strong>负责人方向</strong></p><p class="small muted" style="margin-top:6px">${esc(m.direction||'尚未补充')}</p><div class="banner" style="margin-top:14px">${m.status==='已完成'?'已依据你在演示中录入的人工结论标记完成。没有真实业务结果核验。':'模型回答、本轮执行结束或模拟入队，都不代表客户接受或业务完成。'}</div>${m.paused?'<p class="error" style="margin-top:12px">客户发送已暂停（演示），旧审批不可继续使用</p>':''}<div class="mission-actions"><button class="btn small" data-evaluate="${m.id}">查看业务评测</button>${m.status!=='已完成'?`<button class="btn small" data-direction="${m.id}">补充任务方向</button><button class="btn small" data-pause="${m.id}">${m.paused?'恢复客户发送（模拟）':'暂停客户发送（模拟）'}</button><button class="btn small primary" data-complete="${m.id}">人工验收</button>`:''}</div>${m.eval?`<div class="subpanel" style="margin-top:14px;background:var(--elevated)"><h3>演示评测 · ${m.status==='已完成'?'人工标记完成':'仍需业务验收'}</h3><p class="small">商机当前阶段：${stages[lead(m.leadId).stage]}</p><p class="small">本地跟进任务：${state.tasks.filter(t=>t.leadId===m.leadId).length} 条</p><p class="small">真实发送回执：0 · 客户真实回复：0</p><p class="small muted">仅展示模拟记录，无法证明客户接受报价或交期</p></div>`:''}<div class="divider"></div><h3>任务与策略记录</h3><ul class="audit">${m.history.map(h=>`<li>${esc(h)}</li>`).join('')}</ul></div>`}
function overlay(content){return `<div class="overlay" data-overlay><section class="drawer" role="dialog" aria-modal="true" aria-label="CRM 详情">${content}</section></div>`}function closeButton(){return `<button class="btn ghost iconbtn" data-action="close" aria-label="关闭详情">${icon('close',20)}</button>`}
function openDrawer(kind,id){state.drawer={kind,id};state.drawerTab='info';render();document.querySelector('.drawer [data-action="close"]')?.focus()}
function modal(title,body,onSubmit){const o=document.createElement('div');o.className='overlay modal-overlay';o.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modalhead row between"><h2>${esc(title)}</h2><button class="btn ghost iconbtn" data-dismiss aria-label="关闭弹窗">${icon('close')}</button></div><form class="modalbody">${body}<div class="form-actions"><button type="button" class="btn" data-dismiss>取消</button><button class="btn primary" type="submit">确认</button></div></form></section>`;document.body.appendChild(o);o.addEventListener('click',e=>{if(e.target===o||e.target.closest('[data-dismiss]'))o.remove()});o.querySelector('form').addEventListener('submit',e=>{e.preventDefault();if(onSubmit(new FormData(e.currentTarget))!==false)o.remove()});o.querySelector('input,textarea,button')?.focus()}
function newLead(stage=0){modal('新建演示商机',`<div class="formgrid"><label class="field">商机名称<input class="input" name="title" required maxlength="80" placeholder="例如：企业官网改版"></label><label class="field">联系人<select name="cid">${state.contacts.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><div class="contentgrid"><label class="field">金额（元）<input class="input" name="value" type="number" min="0" max="999999999" step="1" value="12000" required></label><label class="field">阶段<select name="stage">${stages.map((s,i)=>`<option value="${i}" ${i===stage?'selected':''}>${s}</option>`).join('')}</select></label></div><p class="small subtle">只添加到当前页面，刷新后重置。请勿填写真实个人信息。</p></div>`,f=>{const title=String(f.get('title')).trim();if(!title)return false;state.leads.push({id:'l'+Date.now(),title,cid:f.get('cid'),value:Number(f.get('value')),stage:Number(f.get('stage')),risk:false,activity:'刚刚',next:'尚未安排跟进',notes:'在当前交互演示中创建的商机'});render();toast('已在演示中添加商机')})}
function newContact(){modal('新建演示联系人',`<div class="formgrid"><label class="field">姓名<input class="input" name="name" required maxlength="30" placeholder="演示联系人"></label><label class="field">公司<input class="input" name="company" maxlength="60" placeholder="演示公司"></label><label class="field">演示邮箱<input class="input" name="email" type="email" placeholder="name@example.test"></label><p class="small subtle">仅用于本地体验，请勿输入真实联系信息。</p></div>`,f=>{const name=String(f.get('name')).trim();if(!name)return false;state.contacts.push({id:'c'+Date.now(),name,company:String(f.get('company')),email:String(f.get('email')),source:'手动添加',tag:'待跟进',phone:'未连接'});render();toast('已添加演示联系人')})}
function moveLead(id,stage){const l=lead(id);if(!l||!Number.isInteger(stage)||stage<0||stage>3)throw new Error('商机或阶段无效');const from=l.stage;l.stage=stage;l.activity='刚刚';if(stage===3)l.risk=false;render();if(from!==stage)toast(`已移动至「${stages[stage]}」（仅演示）`);return {id,stage:stages[stage]}}
function delegateLead(id){state.scope=id;state.agent=1;state.mode='act';state.delegate=true;state.acceptance='客户确认报价与交期，商机记录和下一次跟进均已更新';state.task='跟进选中商机，补充下一步任务，并准备需要审核的客户回复。';state.detail=null;navigate('workbench')}
function runAgent(){if(state.busy||!state.task.trim())return false;const l=selectedLead();if(!l){toast('请选择目标商机');return false}const missionEnabled=state.mode==='act'&&Boolean(l)&&state.delegate;if(missionEnabled&&!state.acceptance.trim()){openAgentPanel('settings');toast('请填写业务验收条件');return false}const d={id:'r'+Date.now(),chatId:state.chatId,delegate:missionEnabled,acceptance:missionEnabled?state.acceptance:'',task:state.task,agent:agents[state.agent].name,agentIndex:state.agent,leadId:l.id,mode:state.mode,status:'running',events:[['任务已接收','模拟任务：'+state.task]],final:null,write:false,undone:false,proposal:null,draft:null};state.detail=d;state.task='';state.delegate=false;state.acceptance='';state.busy=true;render();let step=0;const steps=[()=>d.events.push(['读取 CRM 上下文',`${l.title} · ${stages[l.stage]} · ${money(l.value)}（虚构数据）`]),()=>d.events.push(['策略判断',d.mode==='inspect'?'只读模式：不修改 CRM 数据':'可逆内部变更可模拟执行；外部发送必须审核']),()=>{if(d.mode==='act'){const tid='t'+Date.now();state.tasks.push({id:tid,leadId:l.id,title:'跟进：'+l.title});d.write=true;d.taskId=tid;d.events.push(['本地 CRM 变更','已添加明天的跟进任务，可撤销']);if(d.delegate){const m={id:'m'+Date.now(),leadId:l.id,goal:d.task,acceptance:d.acceptance,status:'等待业务结果',paused:false,direction:'',history:['刚刚 · 已建立演示业务任务','刚刚 · Agent 本轮结束；等待业务验收'],eval:false};state.missions.push(m);d.missionId=m.id}}else d.events.push(['上下文观察',l.risk?'该商机需要优先跟进；客户确认仍缺少依据':'已有下一步记录；仍应核对客户的具体需求']);},()=>{const name=contact(l.cid)?.name||'客户';if(d.agentIndex===2||d.mode==='act'){d.draft=`${name}您好，想和您再确认一下本次需求与交付时间。我们会在核对服务范围后提供正式方案，方便时请补充您的期望时间。`;d.proposal=d.mode==='act'?'pending':'draft';d.events.push(['回复草稿已准备','草稿未发送，演示环境没有外部发送通道'])}d.status='completed';d.final=d.agentIndex===3?`当前漏斗有 ${state.leads.length} 个商机，其中 ${state.leads.filter(x=>x.risk).length} 个需要优先跟进。建议先核对停滞原因，再安排负责人处理。以上仅为预设演示结果。`:d.mode==='act'?`已为「${l.title}」模拟创建跟进任务，并准备了客户回复草稿。业务结果仍需人工验收。此次没有调用模型，也没有发送消息。`:`「${l.title}」目前处于「${stages[l.stage]}」，金额 ${money(l.value)}。${l.notes} 建议核对缺失信息并明确下一步。以上为基于虚构数据的预设示例，不是模型分析。`;d.events.push(['本轮已结束','运行结束 ≠ 业务完成 · 无真实发送或模型用量']);state.runs.push(d);state.busy=false;clearInterval(runTimer);runTimer=null;}];runTimer=setInterval(()=>{if(!state.busy)return;steps[step++]();render()},480);return true}
function cancelRun(){clearInterval(runTimer);runTimer=null;state.busy=false;if(state.detail){state.detail.status='cancelled';state.detail.events.push(['模拟已取消','已产生的本地变更仍可撤销']);state.runs.push(state.detail)}render();toast('已取消本次模拟')}
function decideProposal(decision){const d=state.detail;if(!d||d.proposal!=='pending')return;const m=state.missions.find(x=>x.id===d.missionId);if(decision==='approved'&&m?.paused){toast('客户发送策略已暂停，无法模拟批准');return}d.proposal=decision;d.events.push([decision==='approved'?'已模拟批准入队':'提案已拒绝','仅记录界面状态；没有向客户发送任何消息']);if(m){m.status=decision==='approved'?'等待客户':'等待负责人';m.history.push(decision==='approved'?'刚刚 · 草稿已模拟入队，未真实发送':'刚刚 · 负责人拒绝了发送提案')}render();toast(decision==='approved'?'已模拟入队，没有真实发送':'已拒绝演示提案')}
function undo(){const d=state.detail;if(!d?.write||d.undone)return;state.tasks=state.tasks.filter(t=>t.id!==d.taskId);d.undone=true;d.events.push(['补偿变更','已撤销本次运行创建的跟进任务']);render();toast('已撤销本地跟进任务')}
function missionAction(id,action){const m=state.missions.find(m=>m.id===id);if(!m)return;if(action==='evaluate'){m.eval=!m.eval;render();return}const labels={direction:'补充任务方向',pause:m.paused?'恢复客户发送（模拟）':'暂停客户发送（模拟）',complete:'人工验收业务任务'};modal(labels[action],`<div class="formgrid"><p class="small muted">${esc(m.goal)}</p><label class="field">${action==='complete'?'验收结论与依据':action==='pause'?'策略变更原因':'补充方向'}<textarea name="reason" required minlength="5" maxlength="2000" placeholder="请填写至少 5 个字符，供演示记录留痕"></textarea></label><p class="small subtle">${action==='complete'?'这会把演示任务标记为完成，仅记录你的人工判断，不表示真实客户已接受。':action==='pause'?'只控制此 Mission 的客户发送；调查可继续，在途消息可能已送达。恢复不会复活旧审批。本页仅模拟。':'只更新当前演示状态，不调用模型或向客户发送消息。'}</p></div>`,f=>{const reason=String(f.get('reason')).trim();if(reason.length<5){toast('请填写至少 5 个字符');return false}if(action==='direction'){m.direction=reason;m.status='等待新方向执行';m.history.push('刚刚 · 补充方向：'+reason)}if(action==='pause'){m.paused=!m.paused;if(m.paused)for(const r of state.runs)if(r.missionId===m.id&&['approved','pending'].includes(r.proposal))r.proposal='expired';m.history.push('刚刚 · '+(m.paused?'暂停':'恢复')+'发送策略：'+reason)}if(action==='complete'){m.status='已完成';m.history.push('刚刚 · 人工验收：'+reason)}render();toast('演示任务状态已更新')})}
function bind(){document.querySelectorAll('[data-page]').forEach(e=>e.onclick=()=>navigate(e.dataset.page));document.querySelectorAll('[data-lead]').forEach(e=>e.onclick=()=>openDrawer('lead',e.dataset.lead));document.querySelectorAll('[data-contact]').forEach(e=>e.onclick=()=>openDrawer('contact',e.dataset.contact));document.querySelectorAll('[data-mission]').forEach(e=>e.onclick=()=>openDrawer('mission',e.dataset.mission));document.querySelectorAll('[data-delegate-lead]').forEach(e=>e.onclick=()=>delegateLead(e.dataset.delegateLead));document.querySelectorAll('[data-tab]').forEach(e=>e.onclick=()=>{state.drawerTab=e.dataset.tab;render()});document.querySelectorAll('[data-agent]').forEach(e=>e.onclick=()=>{state.agent=Number(e.dataset.agent);state.detail=null;render()});document.querySelectorAll('[data-scenario]').forEach(e=>e.onclick=()=>{state.task=agents[state.agent].scenarios[Number(e.dataset.scenario)][1];if(state.agent===1&&Number(e.dataset.scenario)===1)state.mode='act';render()});document.querySelectorAll('[data-run]').forEach(e=>e.onclick=()=>{if(state.busy)return;state.detail=state.runs.find(x=>x.id===e.dataset.run);state.chatId=state.detail.chatId;state.agent=state.detail.agentIndex;state.agentPanel=null;render()});for(const action of ['evaluate','direction','pause','complete'])document.querySelectorAll('[data-'+action+']').forEach(e=>e.onclick=()=>missionAction(e.dataset[action],action));document.querySelectorAll('[data-action]').forEach(e=>e.onclick=()=>{const a=e.dataset.action;if(a==='new-lead')newLead(Number(e.dataset.stage||0));if(a==='new-contact')newContact();if(a==='close'){state.drawer=null;render()}if(a==='new-chat')newAgentChat();if(a==='agent-settings')openAgentPanel('settings');if(a==='agent-details')openAgentPanel('details');if(a==='close-agent-panel'){state.agentPanel=null;render();document.getElementById('agent-task')?.focus()}if(a==='run')runAgent();if(a==='cancel-run')cancelRun();if(a==='approve')decideProposal('approved');if(a==='reject')decideProposal('rejected');if(a==='undo')undo();if(a==='delegate-new')delegateLead(state.scope);if(a==='reset')modal('重置演示数据','<p class="muted">清除本次页面中的修改、Agent 运行与新建任务，恢复最初的虚构数据。</p>',()=>{clearInterval(runTimer);state=fresh();render();toast('已恢复初始演示数据')})});const on=(id,event,fn)=>{const el=document.getElementById(id);if(el)el.addEventListener(event,fn)};on('board-search','input',e=>{state.q=e.target.value;render()});on('contact-search','input',e=>{state.q=e.target.value;render()});on('board-filter','change',e=>{state.filter=e.target.value;render()});on('contact-tag','change',e=>{state.tag=e.target.value;render()});on('contact-source','change',e=>{state.source=e.target.value;render()});on('detail-stage','change',e=>moveLead(state.drawer.id,Number(e.target.value)));on('agent-scope','change',e=>{state.scope=e.target.value;render()});on('run-mode','change',e=>setAgentMode(e.target.value));on('agent-task','input',e=>{state.task=e.target.value;document.getElementById('run-button').disabled=state.busy||!state.task.trim()});on('acceptance','input',e=>state.acceptance=e.target.value);on('delegate','change',e=>{state.delegate=e.target.checked;render()});document.querySelectorAll('[data-lead-drag]').forEach(e=>e.addEventListener('dragstart',ev=>{ev.dataTransfer.setData('text/plain',e.dataset.leadDrag);ev.dataTransfer.effectAllowed='move'}));document.querySelectorAll('.stage').forEach(e=>{e.addEventListener('dragover',ev=>{ev.preventDefault();e.classList.add('dragover')});e.addEventListener('dragleave',()=>e.classList.remove('dragover'));e.addEventListener('drop',ev=>{ev.preventDefault();e.classList.remove('dragover');const id=ev.dataTransfer.getData('text/plain');if(lead(id))moveLead(id,Number(e.dataset.stage))})});document.querySelector('[data-overlay]')?.addEventListener('click',e=>{if(e.target.hasAttribute('data-overlay')){state.drawer=null;render()}})}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const modal=document.querySelector('.modal-overlay');if(modal)modal.remove();else if(state.drawer){state.drawer=null;render()}else if(state.agentPanel){state.agentPanel=null;render();document.getElementById('agent-task')?.focus()}}if(e.key==='Tab'){const dialog=document.querySelector('.modal-overlay .modal')||document.querySelector('.drawer')||document.querySelector('.agent-sidepanel');if(dialog){const items=[...dialog.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]')];const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}});
