if(document.modelContext?.registerTool){const controller=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:controller.signal})).catch(()=>{})}catch{}};register({name:'read_crm_demo',title:'读取 CRM 演示状态',description:'读取虚构商机、业务任务与模拟运行状态，不访问真实 CRM。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({simulated:true,page:state.page,leads:state.leads.map(l=>({id:l.id,title:l.title,stage:stages[l.stage],value:l.value})),missions:state.missions.map(m=>({id:m.id,status:m.status,goal:m.goal})),modelCalls:0,customerSends:0})});register({name:'navigate_crm_demo',title:'打开 CRM 演示页面',description:'打开完整 CRM 目录中的页面、功能中心或演示详情。',inputSchema:{type:'object',properties:{page:{type:'string',enum:[...Object.keys(navNames),...CRM_CATALOG.map(x=>x.href),'/app/crm','/app/ai','/app/analise','/app/settings']}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input!=='object'||!Object.hasOwn(navNames,input.page))throw new Error('无效页面');navigate(input.page);return{page:state.page,simulated:true}}});register({name:'move_demo_lead',title:'移动演示商机',description:'只修改当前页面的虚构商机阶段；不写入真实 CRM，刷新后恢复。',inputSchema:{type:'object',properties:{leadId:{type:'string'},stageIndex:{type:'integer',minimum:0,maximum:3}},required:['leadId','stageIndex'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input!=='object')throw new Error('参数无效');return{simulated:true,...moveLead(input.leadId,input.stageIndex)}}});window.addEventListener('pagehide',()=>controller.abort(),{once:true})}
